import { Drawer } from '@refy-design/web';
import { HelpField } from '@refy-design/web';
import { Input } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
export function Example() {
  const args: Pick<
    ComponentProps<typeof HelpField>,
    'label' | 'helpText' | 'children'
  > = {
    label: 'Capacity allocation',
    helpText: 'Percentage reserved for the owning team.',
    children: <Input id="share-drawer" placeholder="E.g. 40" suffix="%" />,
  };
  const [open, setOpen] = useState(false);
  return (
    <>
      <HelpField {...args} onLearnMore={() => setOpen(true)} />
      <Drawer
        open={open}
        onOpenChange={setOpen}
        side="right"
        title="Capacity allocation"
      >
        <p style={{ margin: 0, lineHeight: 1.6 }}>
          Long in-app help: how the settings assign tasks between person and team, with
          examples and rules.
        </p>
      </Drawer>
    </>
  );
}
